struct Row {
    text: String
}
fn produce(value: int) -> String { return format("done:${value}") }
fn main() {
    var row = Row{text: format("row:${7}")}
    var values = [format("v:${8}")]
    values.push(format("v:${9}"))
    println(row.text)
    println(values[0])
    println(values[1])
    row.text = produce(10)
    println(row.text)
}

struct Row {
    left: String
    right: String
}
fn fail(label: str) -> String ! String { return err(label.toString()) }
fn failInt() -> int ! String { return err("call".toString()) }
fn use(first: String, second: int) -> int { return first.len() + second }
fn vector() -> Vec[String] ! String {
    return [format("first:${1}"), try fail("vec")]
}
fn object() -> Row ! String {
    return Row{left: format("left:${2}"), right: try fail("struct")}
}
fn argument() -> int ! String {
    return use(format("arg:${3}"), try failInt())
}
fn checkVector() {
    let _ = vector() catch error {
        println(error)
        return
    }
}
fn checkObject() {
    let _ = object() catch error {
        println(error)
        return
    }
}
fn checkArgument() {
    let _ = argument() catch error {
        println(error)
        return
    }
}
fn main() {
    checkVector()
    checkObject()
    checkArgument()
}

fn fail(label: str) -> int ! String { return err(label.toString()) }
fn printFailure() -> () ! String {
    println("BAD:${"hold".toString()}:${try fail("print")}:TAIL")
}
fn stderrFailure() -> () ! String {
    eprintln("BAD:${format("hold")}:${try fail("stderr")}:TAIL")
}
fn formatFailure() -> String ! String {
    return format("BAD:${format("hold")}:${try fail("format")}:TAIL")
}
fn checkPrint() {
    let _ = printFailure() catch error {
        println(error)
        return
    }
}
fn checkStderr() {
    let _ = stderrFailure() catch error {
        println(error)
        return
    }
}
fn checkFormat() {
    let _ = formatFailure() catch error {
        println(error)
        return
    }
}
fn main() {
    checkPrint()
    checkStderr()
    checkFormat()
}

fn fail() -> int ! String { return err("discarded".toString()) }
fn work() -> int {
    println("BAD:${format("hold")}:${fail() catch error { return 9 }}:TAIL")
    return 0
}
fn main() { println(work()) }

fn choose(value: int) -> int ! String {
    if value == 1 { return value }
    return err("discarded".toString())
}
fn main() {
    var seen = 0
    for value in 0..4 {
        seen += 1
        println("row:${format("hold")}:${choose(value) catch error { if value == 0 { continue } else { break } }}")
    }
    println(seen)
}

